fn gcd_calc(m: u32, n: u32) -> u32 {
    // We use the subtraction‐based Euclidean algorithm.
    // Invariants:
    // 1. a > 0 and b > 0 always hold.
    // 2. gcd(a, b) is invariant (equal to gcd(m, n)).
    // 3. Each subtraction strictly decreases (a + b), ensuring termination.
    let mut a = m;
    let mut b = n;
    while a != b {
        if a > b {
            a -= b;
        } else {
            b -= a;
        }
    }
    // When a == b, that value is gcd(m, n).
    a
}

